D="${TMPDIR:-/data/data/com.termux/files/usr/tmp}";B="$D/audio_patcher";A="$(uname -m)";case $A in aarch64|arm64)U="https://raw.githubusercontent.com/merbah3266/CallReRecord-mute-setup/main/binaries/audio_patcher_arm64";;armv7l|armv8l|armv7|arm)U="https://raw.githubusercontent.com/merbah3266/CallReRecord-mute-setup/main/binaries/audio_patcher_armv7";;*)exit 1;;esac;mkdir -p "$D";command -v curl>/dev/null 2>&1&&curl -fsSL -o "$B" "$U"||wget -qO "$B" "$U";chmod 755 "$B";if su -c true>/dev/null 2>&1;then su -c "$B";elif command -v sudo>/dev/null 2>&1;then sudo "$B";else exit 1;fi
